/**
 * Sample data for the showcase.
 *
 * **This is not a real instrument.** Every bar is generated by the seeded random walk
 * below, so the pages look the same on every machine and every reload. Nothing here is a
 * price, a forecast, or a claim about any market.
 *
 * The generator is deliberately dull — MINSTD, integer arithmetic, no `Math.random`, no
 * `Date.now` — for the same reason the test data is: a chart that changes under you is
 * impossible to compare against anything.
 *
 * It looks like `tools/golden/data.mjs` and is deliberately not shared with it. That one
 * feeds the recorded fixtures: changing a single number there invalidates 42,000 recorded
 * answers. This one exists to make a chart look like a chart, and should be free to
 * change for that reason alone. Tying them together would mean a cosmetic tweak here
 * breaking the parity evidence there.
 */

const random = seed => {
    let state = seed
    return () => (state = (state * 48271) % 2147483647) / 2147483647
}

const DAY = 24 * 60 * 60 * 1000

/**
 * Daily bars, weekends skipped.
 *
 * Skipping weekends is the point of the discontinuous scale: two bars either side of a
 * weekend sit next to each other, with no empty gap where Saturday would be.
 */
export const daily = (count = 260, seed = 42) => {
    const next = random(seed)
    const bars = []

    let close = 100
    let index = 0

    while (bars.length < count) {
        const date = new Date(Date.UTC(2023, 0, 2) + index++ * DAY)
        if (date.getUTCDay() === 0 || date.getUTCDay() === 6) continue

        const open = close
        // a slight upward drift, so the chart has a trend to look at rather than noise
        close = Math.round((open + (next() - 0.48) * 4) * 100) / 100

        bars.push({
            date,
            open,
            close,
            high: Math.round((Math.max(open, close) + next() * 2) * 100) / 100,
            low: Math.round((Math.min(open, close) - next() * 2) * 100) / 100,
            volume: Math.round(500_000 + next() * 1_500_000),
        })
    }

    return bars
}

/** Five-minute bars inside one session — for the intraday tick formats. */
export const intraday = (count = 300, seed = 7) => {
    const next = random(seed)
    const start = Date.UTC(2023, 5, 15, 9, 30)

    let close = 100

    return Array.from({ length: count }, (_, index) => {
        const open = close
        close = Math.round((open + (next() - 0.5) * 0.8) * 100) / 100

        return {
            date: new Date(start + index * 5 * 60 * 1000),
            open,
            close,
            high: Math.round((Math.max(open, close) + next() * 0.4) * 100) / 100,
            low: Math.round((Math.min(open, close) - next() * 0.4) * 100) / 100,
            volume: Math.round(10_000 + next() * 90_000),
        }
    })
}

/** A second instrument, for anything that compares two series. */
export const secondary = (count = 260, seed = 1337) => daily(count, seed)
